mapper.sql:
from sys_project p
LEFT JOIN sys_user_project up on p.project_id = up.project_id and up.user_id = #{userId}
LEFT JOIN sys_team t on p.team_id = t.team_id

mapper.select:
select count(1) from sys_project
where team_id = #{teamId} AND project_key = #{projectKey} AND project_state > 0
 AND project_id != #{excludeProjectId}

mapper.update:
update sys_project
project_name = #{projectName}, project_key = #{projectKey}, team_id = #{teamId}, project_icon = #{projectIcon}, project_introduce = #{projectIntroduce}, update_by = #{updateBy}, update_time = #{updateTime}, is_lock = #{lock}, lock_remark = #{lockRemark},
where project_id = #{projectId}
